import{z as E,x as m,o,c as B,q as l,j as n,D as t,d as r,s as i,S as p,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"CompCert 与编译器正确性","description":"","frontmatter":{"title":"CompCert 与编译器正确性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/compcert-correctness.md","filePath":"cs/compcert-correctness.md","lastUpdated":1791063341000}'),C={name:"cs/compcert-correctness.md"};function d(A,a,c,h,f,u){const s=m("Mermaid");return o(),B("div",null,[a[2]||(a[2]=l('<h1 id="compcert-与编译器正确性" tabindex="-1">CompCert 与编译器正确性 <a class="header-anchor" href="#compcert-与编译器正确性" aria-label="Permalink to &quot;CompCert 与编译器正确性&quot;">​</a></h1><div class="epigraph"><p>对 Clight 到汇编的每一遍给出证明：若源有定义行为，目标的观察与源相关。信任基是证明助手核与公理，而不是优化直觉。</p><footer>—— 据 Leroy, Formal Verification of a Realistic Compiler, 2009；对照[证明助手](/cs/proof-assistants) 与[操作语义](/cs/operational-semantics) 整理</footer></div><p>上一课<a href="/cs/dsl-embedding">DSL</a> 仍可能错降。缺口是<strong>经证明的编译</strong>：CompCert。本课钉模拟关系与「不证明 UB 源」，模糊测试下一课是另一条质量路。不重写 CIC。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>优化编译器大，测试覆盖不到全部变换。<a href="/cs/type-soundness">健全性</a> 是语言的；这里是<strong>编译器</strong>的：\\(\\mathrm{beh}(S) \\supseteq \\mathrm{beh}(C(S))\\) 一类（具体陈述看论文：未定义可更任意）。缺口是<strong>逐遍证明</strong>，不是 lex。</p><p>CompCert 不覆盖全部 GCC 优化，换保证。</p><h3 id="正确性不是「生成代码很快」" tabindex="-1">正确性不是「生成代码很快」 <a class="header-anchor" href="#正确性不是「生成代码很快」" aria-label="Permalink to &quot;正确性不是「生成代码很快」&quot;">​</a></h3><p>性能另测。证明保证语义，不保证最优寄存器分配。</p><p><span class="marginnote">术语翻译：向前/向后模拟是一种「影子戏」论证——要求源语言每走一步，目标语言都能对应走出（若干）步，且可观察行为保持一致。每一遍都对得上影子，逐遍串联，整个编译的语义保持就成立了。</span></p><p><span class="marginnote">Leroy 2009 CACM/POPL 系列。Coq。本课不列全部中间语言名。与 UB 课：源 UB 则定理不约束。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每遍：小步或大步语义 + 向前/向后模拟。组合。抽取 OCaml 编译器。信任：Coq 核、反汇编器、ABI 公理。</p>',12)),(o(),n(p,null,{default:t(()=>[i(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22Clight%22%5D%20--%3E%20P1%5B%22%E5%B7%B2%E8%AF%81%E9%81%8D%22%5D%0A%20%20P1%20--%3E%20ASM%5B%22%E6%B1%87%E7%BC%96%22%5D%0A%20%20SRC%20--%3E%20SIM%5B%22%E6%A8%A1%E6%8B%9F%E5%85%B3%E7%B3%BB%22%5D%0A%20%20ASM%20--%3E%20SIM%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[r("与"),e("a",{href:"/cs/ssa-form"},"SSA"),r("：CompCert 有自己的 SSA 与证明负担。工业 LLVM 用测试+fuzz，少全证。")],-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"常见误区：以为「经过证明的编译器」能让任何 C 程序都正确。定理只承诺：源程序有定义行为时，目标行为与源一致；源一旦触发未定义行为（UB），定理完全不约束——优化器做什么都不算错。保证的边界由源程序的规矩决定，不由编译器决定。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"未模型化的 IO、内联汇编、并发（早期）在保证外。不要把 CompCert 当 C++ 全语言。链接：分离编译有后续工作，点名。",-1)),(o(),n(p,null,{default:t(()=>[i(s,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20THM%5B%22%E9%80%90%E9%81%8D%E6%A8%A1%E6%8B%9F%E5%AE%9A%E7%90%86%22%5D%20--%3E%20PROV%5B%22%E8%A2%AB%E8%AF%81%E6%98%8E%E7%9A%84%E7%BC%96%E8%AF%91%E9%81%8D%22%5D%0A%20%20PROV%20--%3E%20EXT%5B%22%E6%8A%BD%E5%8F%96%E4%B8%BA%20OCaml%20%E4%BB%A3%E7%A0%81%22%5D%0A%20%20EXT%20--%3E%20RUN%5B%22%E8%BF%90%E8%A1%8C%E6%97%B6%E4%BE%9D%E8%B5%96%20OCaml%20%E7%8E%AF%E5%A2%83%22%5D%0A%20%20T1%5B%22%E4%BF%A1%E4%BB%BB%E5%9F%BA%3A%20Coq%20%E6%A0%B8%E5%BF%83%E6%A0%B8%E5%AF%B9%E5%99%A8%22%5D%20-.-%3E%20PROV%0A%20%20T2%5B%22%E4%BF%A1%E4%BB%BB%E5%9F%BA%3A%20%E5%8F%8D%E6%B1%87%E7%BC%96%E5%99%A8%E4%B8%8E%20ABI%20%E5%85%AC%E7%90%86%22%5D%20-.-%3E%20EXT%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p>抽取代码仍要 OCaml 运行时——信任基。</p><p><span class="marginnote">直觉类比：信任基就像地基的面积。普通编译器的「可信」建立在几十万行代码加海量测试上，地基巨大；CompCert 把地基缩到一个小的证明核对器加少数公理——需要信任的东西越少，「编译器藏着 bug」的面就越小。这就是「换保证」的实质。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Csmith。后课默认：现实编译器可形式化子集。下一课编译器模糊测试 Csmith。</p><p>也不把 CompCert 当电子设计自动化。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CompCert：逐遍模拟，定义行为被保留。</li><li>UB 源不在定理内；优化范围小于 GCC。</li><li>信任基是助手核与公理。</li><li>出处：Leroy, 2009；对照 Wright–Felleisen、Coq。</li></ul>',7))])}const T=E(C,[["render",d]]);export{S as __pageData,T as default};
